changes.old:
    p12-password: ${{ secrets.APPLE_CERT_P12_PASSWORD }}
    keychain: mixel-build

- name: Preflight generated support source and reporter

changes.new:
      run: bash -n scripts/apply-branding.sh scripts/local/sign-and-publish-macos.sh
windows-packaging:
  if: ${{ !(github.event_name == 'workflow_dispatch' && inputs.receiver_native_only) }}
  runs-on: ${{ github.event_name == 'workflow_dispatch' && inputs.windows_source_runner == 'windows-2025' && 'windows-2025' || 'windows-2022' }}
  timeout-minutes: 240
